"""Small deterministic local sandbox for simulated code-agent evaluation."""

from __future__ import annotations

import os
import subprocess
import sys
import tempfile
from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True, slots=True)
class TestOutcome:
    exit_code: int
    stdout: str
    stderr: str
    timed_out: bool = False


class LocalCodeSandbox:
    """Executes only artifacts generated by the deterministic simulator.

    This is a test harness, not a hardened hostile-code sandbox. A production
    CodeAgent adapter must use a container or VM boundary.
    """

    def __init__(self, root: str | Path | None = None) -> None:
        self._temporary: tempfile.TemporaryDirectory[str] | None = None
        if root is None:
            self._temporary = tempfile.TemporaryDirectory(prefix="vskill-sim-")
            self.root = Path(self._temporary.name)
        else:
            self.root = Path(root).resolve()
            self.root.mkdir(parents=True, exist_ok=True)
        self.artifact = self.root / "hello.py"

    def generate(self, expected_output: str, *, buggy: bool) -> Path:
        output = "incorrect output" if buggy else expected_output
        self.artifact.write_text(f"print({output!r})\n", encoding="utf-8")
        return self.artifact

    def fix(self, expected_output: str) -> Path:
        return self.generate(expected_output, buggy=False)

    def run(self, *, timeout_seconds: float = 2.0) -> TestOutcome:
        if not self.artifact.exists():
            return TestOutcome(127, "", "artifact does not exist")
        try:
            completed = subprocess.run(
                [sys.executable, "-I", str(self.artifact)],
                cwd=self.root,
                env={"PATH": os.environ.get("PATH", ""), "PYTHONIOENCODING": "utf-8"},
                capture_output=True,
                text=True,
                timeout=timeout_seconds,
                check=False,
            )
        except subprocess.TimeoutExpired as exc:
            return TestOutcome(
                exit_code=124,
                stdout=exc.stdout or "",
                stderr=exc.stderr or "execution timed out",
                timed_out=True,
            )
        return TestOutcome(completed.returncode, completed.stdout, completed.stderr)

    def verify_output(self, expected_output: str) -> TestOutcome:
        outcome = self.run()
        if outcome.exit_code != 0:
            return outcome
        if outcome.stdout.strip() != expected_output:
            return TestOutcome(
                exit_code=1,
                stdout=outcome.stdout,
                stderr=(
                    f"output mismatch: expected {expected_output!r}, "
                    f"got {outcome.stdout.strip()!r}"
                ),
            )
        return outcome

    def close(self) -> None:
        if self._temporary is not None:
            self._temporary.cleanup()
            self._temporary = None
